{
  "findings": [
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "Roblox collects username, display name, user ID, game metrics, UGC transaction details, and regional location based on IP address.",
      "stance": "risk",
      "quote": "with will have access to your username, display name, user ID, game metrics, UGC transaction details, and your regional location (which we base on your IP address)."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "Roblox may disclose information to advertisers and advertising measurement companies for ad selection and effectiveness measurement, including contact identifiers and device identifiers.",
      "stance": "risk",
      "quote": "In accordance with applicable laws, Roblox may disclose information collected from or about you with advertisers and/or advertising measurement companies to select advertisements for you, or measure and improve advertising effectiveness. Data disclosed for advertising measurement purposes includes contact identifiers and device identifiers."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "Roblox may share users’ personal information such as billing information or usernames with third‑party agents, contractors, or service providers who perform services on Roblox’s behalf.",
      "stance": "risk",
      "quote": "Roblox may share users’ information, including Personal Information like billing information or usernames, with our third‑party agents, contractors, or service providers who are hired to perform services on Roblox’s behalf."
    },
    {
      "ref": "[D502]",
      "area": "age_gating",
      "claim": "Accounts created by users under 13 are automatically set to privacy‑protective settings by default.",
      "stance": "mitigation",
      "quote": "Please note that when users under the age of 13 register for the Service, their account is automatically set to to privacy-protective settings by default."
    },
    {
      "ref": "[D502]",
      "area": "age_gating",
      "claim": "When a child creates an account, Roblox processes the child's username, password, birthdate, and gender (optional) and may use the parent's email to notify the parent and obtain consent.",
      "stance": "mitigation",
      "quote": "When a child creates an account on Roblox, we may process a username, password, birthdate, and gender (gender is optional). Separate from account creation, users may optionally provide the user access to the Service and to communicate with the parent about the child’s account (if a parent email was provided)."
    },
    {
      "ref": "[D502]",
      "area": "contact",
      "claim": "Roblox does not allow strangers to message or voice chat with a child by default; such features are disabled for users under 13.",
      "stance": "mitigation",
      "quote": "Please note that when users under the age of 13 register for the Service, their account is automatically set to to privacy-protective settings by default. This means that these users will not have access to certain features, including personalized advertising, and certain types of notification alerts."
    }
  ]
}
